import sys

def solve():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return

    a = data[0]
    b = data[1]

    has_one_a = '1' in a
    has_one_b = '1' in b

    if has_one_a == has_one_b:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
